import{_ as i,a0 as r,w as o,s as d,I as n,x as t,a1 as e,A as p,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"為何你的 Python 代碼應是扁平與稀疏的 | LCTT x X-CMD","titleTemplate":false,"description":"為何你的 Python 代碼應是扁平與稀疏的 | LCTT (202004) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為何你的 Python 代碼應是扁平與稀疏的 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為何你的 Python 代碼應是扁平與稀疏的 | LCTT (202004) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202004/20191224 Why your Python code should be flat and sparse","title":"為何你的 Python 代碼應是扁平與稀疏的","tag":"202004","desc":""},"relativePath":"202004/20191224 Why your Python code should be flat and sparse.md","filePath":"[post].md"}'),u={name:"202004/20191224 Why your Python code should be flat and sparse.md"};function h(f,s,m,b,y,g){const a=r("Link");return o(),d("div",null,[s[20]||(s[20]=n("h1",{id:"為何你的-python-代碼應是扁平與稀疏的",tabindex:"-1"},[t("為何你的 Python 代碼應是扁平與稀疏的 "),n("a",{class:"header-anchor",href:"#為何你的-python-代碼應是扁平與稀疏的","aria-label":"Permalink to “為何你的 Python 代碼應是扁平與稀疏的”"},"​")],-1)),s[21]||(s[21]=n("blockquote",null,[n("p",null,"本文是 Python 之禪特別系列的第三篇，此篇着眼於其中第五與第六條原則：扁平與稀疏。")],-1)),s[22]||(s[22]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202004/08/191645uiniiy56keig95gi.jpg",alt:""})],-1)),n("p",null,[e(a,{href:"https://www.python.org/dev/peps/pep-0020/"},{default:p(()=>[...s[0]||(s[0]=[t("Python 之禪",-1)])]),_:1}),s[1]||(s[1]=t(" 之所以得名，正是由於它那簡明扼要的規則被設計出的意圖在於讓讀者進行深入地思考，而絕不單是為編程提供一份易於遵守的指南。",-1))]),s[23]||(s[23]=l(`<p>讀後不去三思其意，斷然難以體會 Python 之禪的妙處。倘若 Python 之禪僅僅羅列出一組清晰的法則，那法則之間的矛盾是一種缺憾，然而作為引導讀者沉思最優方案沉思的工具，矛盾卻是絕佳的。</p><h3 id="扁平勝過嵌套flat-is-better-than-nested" tabindex="-1"><ruby>扁平勝過嵌套<rt>Flat is better than nested</rt></ruby> <a class="header-anchor" href="#扁平勝過嵌套flat-is-better-than-nested" aria-label="Permalink to “扁平勝過嵌套Flat is better than nested”">​</a></h3><p>迫於對縮進的強硬要求，Python 對“扁平化”的需求顯然遠超它者。其餘編程語言為了緩解對縮進的需求，通常會在嵌套結構里加入一種“作弊”的手段。為了理解這一點，不妨一同來看看 JavaScript。</p><p>JavaScript 本質上是異步的，這意味着程序員用 JavaScript 寫的代碼會用到大量的回調函數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a(function(resultsFromA) {</span></span>
<span class="line"><span>  b(resultsFromA, function(resultsfromB) {</span></span>
<span class="line"><span>    c(resultsFromC, function(resultsFromC) {</span></span>
<span class="line"><span>      console.log(resultsFromC)</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>忽略這段代碼的具體內容，只去觀察這段代碼的形狀與縮進帶來一個最右邊的點的方式。這種獨特的“箭頭”圖形在我們掃看代碼時格外扎眼，這種寫法也因此被視作不可取，甚至得到了“回調地獄”的綽號。不過，在 JavaScript 中，這種反映嵌套關係的縮進可以通過“作弊”來回避。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a(function(resultsFromA) {</span></span>
<span class="line"><span>b(resultsFromA,</span></span>
<span class="line"><span>  function(resultsfromB) {</span></span>
<span class="line"><span>c(resultsFromC,</span></span>
<span class="line"><span>  function(resultsFromC) {</span></span>
<span class="line"><span>    console.log(resultsFromC)</span></span>
<span class="line"><span>}}}</span></span></code></pre></div><p>Python 並沒有提供這種作弊手段：每一級嵌套在代碼中都如實的對應着一層縮進。因此，Python 深層的嵌套關係在<em>視覺</em>上也一定是深層嵌套的。這使得“回調地獄”的問題對於 Python 而言要比在 JavaScript 中嚴重得多：嵌套的回調函數必定帶來縮進，而絕無使用花括號來“作弊”的可能。</p>`,8)),n("p",null,[s[3]||(s[3]=t("這項挑戰與 Python 之禪的指導原則相結合後，在我參與的庫中催生出了一個優雅的解決方案。我們在 ",-1)),e(a,{href:"https://twistedmatrix.com/trac/"},{default:p(()=>[...s[2]||(s[2]=[t("Twisted",-1)])]),_:1}),s[4]||(s[4]=t(" 框架裏提出了 deferred 抽象，日後 JavaScript 中流行的 promise 抽象亦是受其啓發而生。正是由於 Python 對整潔代碼的堅守，方能推動 Python 開發者去發掘新的、強力的抽象。",-1))]),s[24]||(s[24]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>future_value = future_result()</span></span>
<span class="line"><span>future_value.addCallback(a)</span></span>
<span class="line"><span>future_value.addCallback(b)</span></span>
<span class="line"><span>future_value.addCallback(c)</span></span></code></pre></div><p>（現代 JavaScript 程序員也許會覺得這段代碼十分眼熟：promise 着實受到了 Twisted 裏 deferred 抽象的深遠影響。）</p><h3 id="稀疏勝過密集sparse-is-better-than-dense" tabindex="-1"><ruby>稀疏勝過密集<rt>Sparse is better than dense</rt></ruby> <a class="header-anchor" href="#稀疏勝過密集sparse-is-better-than-dense" aria-label="Permalink to “稀疏勝過密集Sparse is better than dense”">​</a></h3><p>最易降低代碼密集程度的方法是引入嵌套。這種習慣也正是有關稀疏的原則要隨着前一條提出的原因：在竭盡所能地減少嵌套之後，我們往往會遺留下<em>密集的</em>代碼或數據結構。此處的密集，是指塞進過量信息的小段代碼，它們會導致錯誤發生後的解析變得困難。</p><p>這種密集性唯有通過創造性的思考方可改善，此外別無捷徑。Python 之禪並不為我們提供簡單的解決方案，它只會指明改善代碼的方向，而非提供“如何”去做的嚮導。</p><p>起身走走，泡個熱水澡，抑或是聞聞花香。盤坐冥思，直至靈感襲來。當你終於得到啓發，便是動身寫代碼之時。</p><hr>`,7)),n("p",null,[s[6]||(s[6]=t("via: ",-1)),e(a,{href:"https://opensource.com/article/19/12/zen-python-flat-sparse"},{default:p(()=>[...s[5]||(s[5]=[t("https://opensource.com/article/19/12/zen-python-flat-sparse",-1)])]),_:1})]),n("p",null,[s[11]||(s[11]=t("作者：",-1)),e(a,{href:"https://opensource.com/users/moshez"},{default:p(()=>[...s[7]||(s[7]=[t("Moshe Zadka",-1)])]),_:1}),s[12]||(s[12]=t(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[8]||(s[8]=[t("lujun9972",-1)])]),_:1}),s[13]||(s[13]=t(" 譯者：",-1)),e(a,{href:"https://github.com/caiichenr"},{default:p(()=>[...s[9]||(s[9]=[t("caiichenr",-1)])]),_:1}),s[14]||(s[14]=t(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:p(()=>[...s[10]||(s[10]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[17]||(s[17]=t("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[15]||(s[15]=[t("LCTT",-1)])]),_:1}),s[18]||(s[18]=t(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:p(()=>[...s[16]||(s[16]=[t("Linux中國",-1)])]),_:1}),s[19]||(s[19]=t(" 榮譽推出",-1))])])}const T=i(u,[["render",h]]);export{P as __pageData,T as default};
